style.css:
@-moz-document domain("huggingface.co") {
body {
    background: url("https://i.imgur.com/91535bU.jpg") no-repeat center center fixed;
    background-size: cover !important;
    color: #f0f0f0 !important;
  }
  .block, .card, .container, .main, .navbar, .header {
    background-color: rgba(24, 26, 30, 0.95) !important;
  }
  a {
    color: #4f8cf9 !important;
  }
  a:hover {
    transition: color 0.2s ease-in-out;
    color: #f7a14e !important;
  }
  .button {
    background: linear-gradient(90deg, #4f8cf9, #f7a14e) !important;
    border: none !important;
    border-radius: 5px !important;
    color: #fff !important;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5) !important;
  }
  .button:hover {
    box-shadow: 0 0 15px rgba(247, 161, 78, 0.8) !important;
  }
}
